def gen(rng):
    # tree as parallel lists: vals, L, R
    def ser(vals, L, R, root=0):
        q = [root]
        out = []
        i = 0
        while i < len(q):
            u = q[i]
            i += 1
            if u == -1:
                out.append('null')
                continue
            out.append(str(vals[u]))
            q.append(L[u])
            q.append(R[u])
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def build(sv, mode):
        # build a valid BST over the sorted list sv; returns vals, L, R (root = 0)
        n = len(sv)
        vals, L, R = [], [], []
        stack = [(0, n - 1, -1, 0)]
        while stack:
            lo, hi, par, side = stack.pop()
            if lo > hi:
                continue
            if mode == 'bal':
                m = (lo + hi) // 2
            elif mode == 'right':
                m = lo
            elif mode == 'left':
                m = hi
            elif mode == 'zig':
                m = lo if (hi - lo) % 2 == 0 else hi
            else:
                m = rng.randint(lo, hi)
            vals.append(sv[m])
            L.append(-1)
            R.append(-1)
            idx = len(vals) - 1
            if par != -1:
                if side == 0:
                    L[par] = idx
                else:
                    R[par] = idx
            stack.append((lo, m - 1, idx, 0))
            stack.append((m + 1, hi, idx, 1))
        return vals, L, R

    def mutate(vals, L, R, kind):
        n = len(vals)
        v = list(vals)
        if n < 2:
            return v
        if kind == 'swap':
            a, b = rng.sample(range(n), 2)
            v[a], v[b] = v[b], v[a]
        elif kind == 'dup':
            # copy an ancestor's value into a descendant two or more levels down
            par = {}
            for u in range(n):
                for c in (L[u], R[u]):
                    if c != -1:
                        par[c] = u
            for _ in range(50):
                u = rng.randrange(n)
                a = par.get(u)
                if a is None:
                    continue
                g = par.get(a)
                if g is None:
                    continue
                v[u] = v[g]
                break
        else:
            u = rng.randrange(n)
            v[u] = v[u] + rng.choice([-1, 1])
        return v

    tests = [
        "1", "7", "1000000000", "5 5", "5 null 5", "5 4 6 null null 3 7",
        "10 5 15 null null 6 20", "-1000000000 null 1000000000", "0 -1 1", "2 1 3", "3 1 4 null 2", "1 1 1",
    ]
    for n in (2, 3, 4, 5, 6, 7, 8, 10, 12):
        for mode in ('rand', 'bal', 'zig'):
            sv = sorted(rng.sample(range(-60, 60), n))
            vals, L, R = build(sv, mode)
            tests.append(ser(vals, L, R))
            for kind in ('swap', 'dup', 'bump'):
                if rng.random() < 0.6:
                    tests.append(ser(mutate(vals, L, R, kind), L, R))
    N = 100000
    sv = sorted(rng.sample(range(-10**9, 10**9 + 1), N))
    vals, L, R = build(sv, 'bal')
    tests.append(ser(vals, L, R))
    tests.append(ser(mutate(vals, L, R, 'swap'), L, R))
    vals, L, R = build(sv, 'rand')
    tests.append(ser(vals, L, R))
    tests.append(ser(mutate(vals, L, R, 'dup'), L, R))
    D = 5000
    sv2 = sorted(rng.sample(range(-10**9, 10**9 + 1), D))
    for mode in ('right', 'left', 'zig'):
        vals, L, R = build(sv2, mode)
        tests.append(ser(vals, L, R))
        bad = list(vals)
        bad[len(vals) - 1] = bad[0]
        tests.append(ser(bad, L, R))
    return tests

